const today=()=>new Date().toISOString().slice(0,10);
const dateAdd=(d,n)=>new Date(new Date(d).getTime()+n*86400000).toISOString().slice(0,10);
const days=(a,b)=>(new Date(b)-new Date(a))/86400000;
const id=p=>p+'-'+crypto.randomUUID().slice(0,8).toUpperCase();
const check=(v,m)=>{if(!v)throw Error(m)};
const num=(n,min=0)=>{n=Number(n);check(Number.isFinite(n)&&n>=min,'Invalid quantity or amount');return n};
const qty=n=>{n=num(n,1);check(Number.isInteger(n),'Use whole units');return n};
