 names.forEach((name,i)=>s.items.push({id:'TM-'+String(i+1).padStart(3,'0'),name,barcode:String(100000+i),cost:costs[i],price:i<5?[32,42,30,28,36][i]:Math.round(costs[i]*2.3*100)/100,supplier:'S'+(i%6+1),lead:[7,12,14,5,6,9][i%6],rop:i<5?18:80,stock:i<5?[44+i*7,25+i*3,12+i]:[200+i*5,140+i*3,35+i],bom:i<5?[[5+i,2],[10,1],[14,1],[15,1],[16,1],[17,1]].map(([x,q])=>({item:'TM-'+String(x+1).padStart(3,'0'),qty:q})):[]}));
 s.items[5].stock=[22,18,0];s.items[12].stock=[16,9,0];
 for(let d=210;d>=1;d--){const date=dateAdd(today(),-d);for(let k=0;k<2;k++){let i=(d*7+k)%5,q=1+(d+k)%4,it=s.items[i];s.sales.push({id:'SALE-H'+d+'-'+k,date,customer:s.customers[d%10].id,location:d%3,lines:[{item:it.id,qty:q,price:it.price,cost:it.cost}],revenue:q*it.price,cogs:q*it.cost,tax:q*it.price*.06,discount:0,kind:'sale',historical:true});}}
 s.suppliers.forEach((sup,j)=>{for(let k=0;k<8;k++){let sent=dateAdd(today(),-165+k*21+j),expected=dateAdd(sent,sup.lead),actual=dateAdd(expected,k%4===0?3:-1),it=s.items[5+j];s.pos.push({id:'PO-'+(1000+j*10+k),supplier:sup.id,date:sent,expected,location:0,status:k===7?'Order Sent':'Closed',lines:[{item:it.id,qty:100,received:k===7?0:(k===3?92:100),cost:it.cost}],receipts:k===7?[]:[{date:actual,qty:k===3?92:100}],invoiceDate:k===7?null:actual,paid:k<6?it.cost*(k===3?92:100):0});}});
