const item=(s,x)=>{let i=s.items.find(i=>i.id===x);check(i,'Item not found');return i};
const loc=(s,x)=>{x=num(x);check(Number.isInteger(x)&&s.locations[x],'Invalid location');return x};
function move(s,it,l,n,reason){check(it.stock[l]+n>=0,'Insufficient stock: '+it.name+' at '+s.locations[l]);it.stock[l]+=n;s.movements.unshift({date:new Date().toISOString(),item:it.id,location:l,qty:n,reason});}
function take(s,it,l,q){if(it.bom.length){let finished=Math.min(it.stock[l],q),remaining=q-finished;if(finished)move(s,it,l,-finished,'Finished goods sale');for(const b of it.bom){const c=item(s,b.item);if(remaining)move(s,c,l,-remaining*b.qty,'Kit assembled at sale: '+it.id)}return (finished*it.cost+remaining*it.bom.reduce((a,b)=>a+item(s,b.item).cost*b.qty,0))/q}move(s,it,l,-q,'Sale');return it.cost}
